mapper.select:
SELECT center_code, yy, mm, class_key, unit_key, sub_unit_key
FROM erp_person_year
WHERE center_code = #{centerCode}
  AND yy = #{yy}
ORDER BY mm, class_key;

mapper.update:
UPDATE erp_order_deadline
SET dead_line_at = #{deadline}
WHERE center_code = #{centerCode}

mapper.select:
SELECT DISTINCT t.user_code AS userCode, u.user_name AS userName
FROM erp_time_table t
         JOIN erp_user u ON u.user_code = t.user_code
WHERE t.center_code = #{centerCode}
  AND t.yy = #{year}

SELECT mm, content
FROM erp_yearly_event
WHERE center_code = #{centerCode}
  AND yy = #{year}

mapper.delete:
DELETE FROM erp_yearly_event
WHERE center_code = #{centerCode}
  AND yy = #{year}
  AND mm = #{month}
